//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns `true` for transient errors, which the retry policy may
    /// retry. Permanent errors are never retried.
    pub fn is_transient(&self) -> bool {
        matches!(self, RetryError::Transient(_))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn transient_errors_are_retryable() {
        assert!(RetryError::Transient("blip".into()).is_transient());
    }

    #[test]
    fn permanent_errors_are_not_retryable() {
        assert!(!RetryError::Permanent("bad input".into()).is_transient());
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Upper bound on the delay before any retry, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Delay before the retry at 0-based index `retry_index`
    /// (0 = before the second overall attempt).
    ///
    /// The delay doubles on every retry, starting at `base_delay_ms`,
    /// and saturates at `max_delay_ms`. Because it saturates, the
    /// computation never overflows `u64`, even for very large retry
    /// indexes or base delays.
    pub fn delay_ms(&self, retry_index: u32) -> u64 {
        let max = self.max_delay_ms;
        let mut delay = self.base_delay_ms.min(max);
        for _ in 0..retry_index {
            if delay == 0 || delay >= max {
                break;
            }
            delay = delay.saturating_mul(2).min(max);
        }
        delay
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    #[test]
    fn delay_grows_exponentially_from_base() {
        let config = config(5, 100, u64::MAX);
        assert_eq!(config.delay_ms(0), 100);
        assert_eq!(config.delay_ms(1), 200);
        assert_eq!(config.delay_ms(2), 400);
        assert_eq!(config.delay_ms(3), 800);
    }

    #[test]
    fn delay_saturates_at_max_delay() {
        let config = config(10, 100, 350);
        assert_eq!(config.delay_ms(0), 100);
        assert_eq!(config.delay_ms(1), 200);
        assert_eq!(config.delay_ms(2), 350);
        assert_eq!(config.delay_ms(3), 350);
    }

    #[test]
    fn delay_above_safe_exponent_saturates_without_overflow() {
        let config = config(u32::MAX, 1, 1000);
        // 2^63 would overflow u64; the policy must saturate instead.
        assert_eq!(config.delay_ms(63), 1000);
        assert_eq!(config.delay_ms(10_000), 1000);
        assert_eq!(config.delay_ms(u32::MAX), 1000);
    }

    #[test]
    fn base_above_max_delay_saturates_immediately() {
        let config = config(3, 5000, 100);
        assert_eq!(config.delay_ms(0), 100);
        assert_eq!(config.delay_ms(1), 100);
    }

    #[test]
    fn zero_base_delay_stays_zero() {
        let config = config(3, 0, 100);
        assert_eq!(config.delay_ms(0), 0);
        assert_eq!(config.delay_ms(10_000), 0);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
///
/// Only transient errors are retried: a permanent error is returned
/// immediately without further calls. `max_attempts` includes the first
/// call, so `job` is invoked at most `max_attempts` times. Between
/// attempts the policy sleeps for an exponentially growing delay that
/// starts at `base_delay_ms` and saturates at `max_delay_ms`.
///
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let mut attempts: u32 = 0;
    loop {
        attempts += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(err) if !err.is_transient() => return Err(err),
            Err(err) => {
                if attempts >= config.max_attempts {
                    return Err(err);
                }
                let delay = config.delay_ms(attempts - 1);
                sleeper.sleep_ms(delay);
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    #[test]
    fn returns_ok_without_sleeping_on_first_success() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(3, 10, 100), &mut sleeper, || {
            calls += 1;
            Ok(())
        });
        assert_eq!(result, Ok(()));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn permanent_error_returns_immediately() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(5, 10, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("bad input".into()))
        });
        assert_eq!(result, Err(RetryError::Permanent("bad input".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn retries_transient_errors_up_to_max_attempts() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(4, 10, 1000), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("blip".into()))
        });
        assert_eq!(result, Err(RetryError::Transient("blip".into())));
        assert_eq!(calls, 4);
        assert_eq!(sleeper.sleeps, vec![10, 20, 40]);
    }

    #[test]
    fn succeeds_after_transient_retries() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(5, 10, 100), &mut sleeper, || {
            calls += 1;
            if calls < 3 {
                Err(RetryError::Transient("blip".into()))
            } else {
                Ok(())
            }
        });
        assert_eq!(result, Ok(()));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }

    #[test]
    fn max_attempts_one_never_sleeps() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(1, 10, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("blip".into()))
        });
        assert_eq!(result, Err(RetryError::Transient("blip".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn delays_saturate_at_max_delay() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(6, 10, 25), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("blip".into()))
        });
        assert_eq!(result, Err(RetryError::Transient("blip".into())));
        assert_eq!(calls, 6);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25, 25]);
    }
}

//! Integration tests for the public retry policy API.

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
    RetryConfig {
        max_attempts,
        base_delay_ms,
        max_delay_ms,
    }
}

#[test]
fn retries_transient_errors_then_succeeds() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config(4, 5, 100), &mut sleeper, || {
        calls += 1;
        if calls <= 2 {
            Err(RetryError::Transient("temporary lock".into()))
        } else {
            Ok(())
        }
    });
    assert_eq!(result, Ok(()));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![5, 10]);
}

#[test]
fn permanent_error_is_not_retried() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config(5, 5, 100), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("missing job".into()))
    });
    assert_eq!(result, Err(RetryError::Permanent("missing job".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn max_attempts_bounds_total_calls_including_first() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config(3, 1, 100), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("blip".into()))
    });
    assert_eq!(result, Err(RetryError::Transient("blip".into())));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![1, 2]);
}

#[test]
fn delay_growth_saturates_at_max_delay_ms() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config(6, 100, 300), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("blip".into()))
    });
    assert_eq!(result, Err(RetryError::Transient("blip".into())));
    assert_eq!(calls, 6);
    assert_eq!(sleeper.sleeps, vec![100, 200, 300, 300, 300]);
}

#[test]
fn huge_retry_index_does_not_overflow_delay() {
    let config = config(10, 1, 1000);
    assert_eq!(config.delay_ms(10_000), 1000);
}
